<script>
  import Repeat from './Repeat.svelte'

  let klass = ''
  export { klass as class }
  export let contentClass
  export let repeat = 100

  const ariaLabel = $$restProps['aria-label']
  if (!ariaLabel) throw new Error('aria-label is required for text wall')
</script>

<!-- Have to see the Splendid Docs Landing for usage! -->
<div class="Textwall {klass}" aria-label={ariaLabel}>
  <div class="Stack">
    <div class="TextwallBoundary-before Pos-top Foreground">
      <slot name="before" />
    </div>
    <div class="Stack overflow-hidden">
      <div class="TextwallDimensions"></div>
      <div class="TextwallContent {contentClass}">
        <Repeat aria-hidden times={repeat}><slot /></Repeat>
      </div>
    </div>
    <div class="TextwallBoundary-after Pos-bottom Foreground">
      <slot name="after" />
    </div>
  </div>
</div>
